on.click:
() => {if (this.formData.inputN0) {
    this.parentFormItems.select8.componentProps.options.push({
      label: this.formData.inputN0,
      value: this.formData.inputN0,
    })
	this.formItems.btn0.hidden = true
	this.formItems.inputN0.hidden = false
	this.formItems.btn1.hidden = false
	this.formItems.btn2.hidden = false
	this.formData.inputN0 = ''
}}

lifecycle.mounted:
() => {
	const aaa = () => {
		const disabled = []
  for (let i = 0; i < 24; i++) {
    if (i < 9 || i > 17) disabled.push(i); // 禁用9点之前和18点之后的小时
  }
  return disabled
	}

  this.formItems.time4.componentProps.disabledHours = aaa
 }

()=>{
	this.request.post({
		url: '/data/dictData',
		data: { dictCode: 'sys_sex' }
	}).then((res)=>{
		if(res.code == 200){
			this.formItems.transfer2.componentProps.data = [...res.data.data]
		} else {
			this.message({type: 'error', message: '获取数据失败！'})
		}
	}).catch((err)=>{
		this.message({type: 'error', message: '请求失败！'})
	})

}

()=>{
	this.request.post({
		url: '/data/dictData',
		data: { dictCode: 'sys_menu' }
	}).then((res)=>{
		if(res.code == 200){
			const treeData = this.treeUtil.listToTree(res.data.data, {id: 'permission_id', children: 'children', pid: 'parent_id'})
			this.formItems.treeSelect2.componentProps.data = treeData
		} else {
			this.message({type: 'error', message: '获取数据失败！'})
		}
	}).catch((err)=>{
		this.message({type: 'error', message: '请求失败！'})
	})

}

inputNumber1.validator:
(_, val, callback) => {
	if(val < this.formData.inputNumber4){
		callback(new Error('需要大于 按钮位置'))
	} else {
		callback()
	}
}
